def compute(vars):
    old_price = vars["v1"]
    new_price = vars["v2"]
    change = new_price - old_price
    if old_price == 0:
        return None
    growth_rate = change / old_price
    return {
        "value": growth_rate,
        "trace": {
            "old_price": old_price,
            "new_price": new_price,
            "change": change,
            "growth_rate": growth_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
